function validate([grid]) {
  if (grid.length < 1 || grid.length > 20) return 'grid needs 1 to 20 rows.';
  const n = grid[0].length;
  if (n < 1 || n > 20) return 'Each row needs 1 to 20 cells.';
  const counts = { S: 0, B: 0, T: 0 };
  for (const row of grid) {
    if (row.length !== n) return 'All rows must have the same length.';
    for (const cell of row) {
      if (!['.', '#', 'S', 'B', 'T'].includes(cell)) return "Cells are '.', '#', 'S', 'B' or 'T'.";
      if (cell in counts) counts[cell]++;
    }
  }
  if (counts.S !== 1 || counts.B !== 1 || counts.T !== 1) return "The grid needs exactly one 'S', one 'B' and one 'T'.";
  return null;
}

