function minPushBox(grid) {
  const width = grid[0].length + 2;
  const wall = '#'.repeat(width);
  const cells = wall + grid.map(row => '#' + row.join('') + '#').join('') + wall;
  const target = cells.indexOf('T');
  const visited = new Set();
  let frontier = [[cells.indexOf('B'), cells.indexOf('S')]];

  for (let pushes = 0; frontier.length > 0; pushes++) {
    const next = [];
    for (const [box, player] of frontier) {
      if (box === target) return pushes;
      const seen = new Set([player]);
      for (const cell of seen) {
        if (cells[cell] !== '#' && cell !== box) {
          seen.add(cell - width).add(cell + width).add(cell - 1).add(cell + 1);
        }
      }
      for (const step of [-width, width, -1, 1]) {
        const ahead = box + step;
        const behind = box - step;
        if (cells[ahead] === '#' || cells[behind] === '#' || !seen.has(behind)) continue;
        const key = ahead * cells.length + box;
        if (visited.has(key)) continue;
        visited.add(key);
        next.push([ahead, box]);
      }
    }
    frontier = next;
  }
  return -1;
}

