function minPushBox(grid) {
  // 0-1 BFS over every (player cell, box cell) pair: a walk costs 0 pushes, a push costs 1.
  const m = grid.length, n = grid[0].length, cells = m * n;
  const open = (r, c) => r >= 0 && r < m && c >= 0 && c < n && grid[r][c] !== '#';
  let s = 0, b = 0, t = 0;
  for (let r = 0; r < m; r++) for (let c = 0; c < n; c++) {
    if (grid[r][c] === 'S') s = r * n + c;
    if (grid[r][c] === 'B') b = r * n + c;
    if (grid[r][c] === 'T') t = r * n + c;
  }
  const dist = new Array(cells * cells).fill(Infinity);
  dist[s * cells + b] = 0;
  // The deque is `front` (a stack of cost-0 moves) followed by `back` (cost-1 moves, read from backHead).
  const front = [], back = [s * cells + b];
  let backHead = 0;
  const dirs = [[0, 1], [1, 0], [0, -1], [-1, 0]];
  while (front.length || backHead < back.length) {
    const state = front.length ? front.pop() : back[backHead++];
    const p = Math.floor(state / cells), bx = state % cells;
    const d = dist[state];
    if (bx === t) return d;
    const pr = Math.floor(p / n), pc = p % n, brow = Math.floor(bx / n), bcol = bx % n;
    for (const [dr, dc] of dirs) {
      const nr = pr + dr, nc = pc + dc;
      if (!open(nr, nc)) continue;
      if (nr === brow && nc === bcol) {
        const tr = brow + dr, tc = bcol + dc;
        if (!open(tr, tc)) continue;
        const nextState = bx * cells + tr * n + tc;
        if (dist[nextState] > d + 1) { dist[nextState] = d + 1; back.push(nextState); }
      } else {
        const nextState = (nr * n + nc) * cells + bx;
        if (dist[nextState] > d) { dist[nextState] = d; front.push(nextState); }
      }
    }
  }
  return -1;
}

