function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  for (;;) {
    const tiny = size === 'small' && rand() < 0.25;
    const m = size === 'large' ? int(15, 20) : tiny ? int(1, 3) : int(3, 6);
    const n = size === 'large' ? int(15, 20) : tiny ? int(1, 3) : int(3, 6);
    if (m * n < 3) continue;
    const density = rand() * (size === 'large' ? 0.3 : 0.25);
    const border = size === 'large' && rand() < 0.5;
    const grid = Array.from({ length: m }, (_, r) => Array.from({ length: n }, (_, c) =>
      border && (r === 0 || c === 0 || r === m - 1 || c === n - 1) ? '#' : rand() < density ? '#' : '.'));
    const inside = [];
    for (let r = 0; r < m; r++) for (let c = 0; c < n; c++) if (!border || (r > 0 && c > 0 && r < m - 1 && c < n - 1)) inside.push([r, c]);
    for (let i = inside.length - 1; i > 0; i--) { const j = int(0, i); [inside[i], inside[j]] = [inside[j], inside[i]]; }
    // Most boxes start away from the outer edge, where they could still be pushed in every direction.
    const middle = inside.findIndex(([r, c]) => r > 0 && c > 0 && r < m - 1 && c < n - 1);
    if (middle > 0 && rand() < 0.75) [inside[0], inside[middle]] = [inside[middle], inside[0]];
    ['B', 'S', 'T'].forEach((ch, i) => { grid[inside[i][0]][inside[i][1]] = ch; });
    return [grid];
  }
}
